function formVal(root,name){const e=$('[name="'+name+'"]',root);return e?String(e.value||'').trim():''}
function recomputeIdentSummary(directory){const rows=directory&&directory.rows||[];directory.summary={total:rows.length,complete:rows.filter(r=>num(r.completion_percent)>=100).length,incomplete:rows.filter(r=>num(r.completion_percent)>=1&&num(r.completion_percent)<100).length,not_started:rows.filter(r=>num(r.completion_percent)===0).length,ready:rows.filter(r=>num(r.completion_percent)>=100&&norm(r.workflow_status)==='SUBMITTED').length,verified:rows.filter(r=>norm(r.workflow_status)==='VERIFIED').length};return directory}
function updateDirectoryRow(directory,row){if(!directory||!row)return directory;const rows=directory.rows||[],i=rows.findIndex(r=>String(r.student_id)===String(row.student_id));if(i>=0)rows[i]=Object.assign({},rows[i],row);else rows.push(row);directory.rows=rows;directory.count=rows.length;return recomputeIdentSummary(directory)}
function saveProfile(mount,ctx,p,directory,btn,next){
 const root=$('[data-t83-ident]',mount)||mount,st=p.student||{},allow=p.allowed_actions||{},c=ctxIds();
 const payload={date_of_birth:formVal(root,'date_of_birth')||null,boarding_type:formVal(root,'boarding_type')||null,birth_cert_nid_no:formVal(root,'birth_cert_nid_no')||null,other_important_information:formVal(root,'other_important_information')||null,father_guardian_name:formVal(root,'father_guardian_name')||null,father_guardian_id:formVal(root,'father_guardian_id')||null,father_guardian_phone:formVal(root,'father_guardian_phone')||null,mother_guardian_name:formVal(root,'mother_guardian_name')||null,mother_guardian_id:formVal(root,'mother_guardian_id')||null,mother_guardian_phone:formVal(root,'mother_guardian_phone')||null,guardian_name:formVal(root,'guardian_name')||null,guardian_phone:formVal(root,'guardian_phone')||null,district:formVal(root,'district')||null,sector:formVal(root,'sector')||null,cell:formVal(root,'cell')||null,village:formVal(root,'village')||null,remarks:formVal(root,'remarks')||null};
 const required=['date_of_birth','father_guardian_name','father_guardian_id','father_guardian_phone','mother_guardian_name','mother_guardian_id','mother_guardian_phone','sector','cell','village'],submit=required.every(k=>!!payload[k]);
 const hp=allow.edit_health?{has_disease:formVal(root,'has_disease')==='true',disease_type:formVal(root,'disease_type')||null,disease_details:formVal(root,'disease_details')||null,has_special_need:formVal(root,'has_special_need')==='true',special_need_type:formVal(root,'special_need_type')||null,impairment_type:formVal(root,'impairment_type')||null,severity:formVal(root,'severity')||null,care_notes:formVal(root,'care_notes')||null}:null;
 const done=busy(btn,next?'SAVING & OPENING NEXT…':'SAVING…');
 rpc('r18685_teacher_save_student_profile',{p_student_id:st.id,p_academic_year_id:c.ayId,p_identity:payload,p_health:hp,p_submit:submit}).then(result=>{
   updateDirectoryRow(directory,result&&result.row);IDENT=directory;IDENT_AT=Date.now();
   flash(mount,submit?'Profile saved and sent for verification.':'Profile saved. Missing required fields remain.','success');
   if(next){const rows=directory&&directory.rows||[],idx=rows.findIndex(r=>String(r.student_id)===String(st.id)),candidate=rows.slice(idx+1).find(r=>r.can_edit&&num(r.completion_percent)<100)||rows.find(r=>r.can_edit&&num(r.completion_percent)<100);if(candidate)return openStudentProfile(mount,ctx,candidate.student_id,directory);renderIdentList(mount,ctx,directory,directory&&directory.__lockedClass||null);flash(mount,'All editable student profiles are complete.','success');return}
   if(result&&result.profile){renderProfileEditor(mount,ctx,result.profile,directory);return}
   renderIdentList(mount,ctx,directory,directory&&directory.__lockedClass||null);
 }).catch(e=>flash(mount,'Save failed: '+errorText(e),'error')).finally(done)
}

/* ========================= ATTENDANCE COMMON ========================= */
function attendanceSummary(rows){let total=rows.length,boys=0,girls=0,present=0,absent=0;rows.forEach(r=>{const sex=norm(r.sex),s=norm(r._status||r.attendance_status||'PRESENT');if(sex==='M'||sex==='MALE')boys++;if(sex==='F'||sex==='FEMALE')girls++;if(s==='PRESENT'||s==='LATE'||s==='SCHOOL_ACTIVITY'||s==='SPORT')present++;else absent++});return{total,boys,girls,present,absent,percent:total?100*present/total:0}}
function attKpis(s){return '<div class="t83-att-summary">'+[['TOTAL',s.total],['BOYS',s.boys],['GIRLS',s.girls],['PRESENT',s.present],['ABSENT',s.absent],['% PRESENT',s.percent.toFixed(1)+'%']].map(x=>'<div class="t83-mini-kpi"><b>'+esc(x[1])+'</b><span>'+x[0]+'</span></div>').join('')+'</div>'}
const ATT_STATUS=['PRESENT','ABSENT','LATE','EXCUSED','SICK','PERMISSION'];
function attRowsHtml(rows){return rows.map((r,i)=>{const s=norm(r.attendance_status||'PRESENT');return '<tr data-att-row="'+esc(r.student_id)+'"><td class="center">'+(i+1)+'</td><td>'+esc(r.sdms_code)+'</td><td class="name">'+esc(r.student_name)+'</td><td class="center">'+esc(r.sex)+'</td><td><select class="t83-status-select" data-att-status>'+ATT_STATUS.map(x=>'<option '+(s===x?'selected':'')+'>'+x+'</option>').join('')+'</select></td><td><input class="t83-reason" data-att-reason value="'+esc(r.reason||'')+'" placeholder="Reason if exception"></td></tr>'}).join('')}
function attMobileHtml(rows){return rows.map(r=>{const s=norm(r.attendance_status||'PRESENT');return '<div class="t83-mobile-card" data-att-row="'+esc(r.student_id)+'"><div class="top"><b>'+esc(r.student_name)+'</b><small>'+esc(r.sex)+' · '+esc(r.sdms_code)+'</small></div><div class="t83-form-grid two"><div class="t83-field"><label>Status</label><select data-att-status>'+ATT_STATUS.map(x=>'<option '+(s===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="t83-field"><label>Reason</label><input data-att-reason value="'+esc(r.reason||'')+'" placeholder="Reason if needed"></div></div></div>'}).join('')}
function syncAttendanceViews(root,source){const row=source.closest('[data-att-row]'),id=row&&row.dataset.attRow;if(!id)return;const status=$('[data-att-status]',row).value,reason=$('[data-att-reason]',row).value;$$('[data-att-row="'+CSS.escape(id)+'"]',root).forEach(x=>{const s=$('[data-att-status]',x),r=$('[data-att-reason]',x);if(s&&s!==source)s.value=status;if(r&&r!==source)r.value=reason});updateAttSummary(root)}
function collectAttendance(root,base,includeFollow=false){return (base||[]).map(r=>{const row=$('[data-att-row="'+CSS.escape(String(r.student_id))+'"]',root),s=row?$('[data-att-status]',row).value:'PRESENT',reason=row?$('[data-att-reason]',row).value:'';return{student_id:r.student_id,attendance_status:s,arrival_time:null,reason:reason||null,teacher_advice:null,...(includeFollow?{follow_up_required:false}:{})}})}
function validateAttendance(rows){const exceptions=new Set(['ABSENT','LATE','EXCUSED','SICK','PERMISSION']);const bad=rows.find(r=>exceptions.has(r.attendance_status)&&!r.reason);return bad?'Reason is required for every absence, late, excused, sick or permission status.':''}
function wireAttendanceRows(root,base){$$('[data-att-status],[data-att-reason]',root).forEach(e=>e.addEventListener(e.tagName==='SELECT'?'change':'input',()=>syncAttendanceViews(root,e)));const all=$('[data-mark-all-present]',root);if(all)all.onclick=()=>{$$('[data-att-status]',root).forEach(s=>s.value='PRESENT');$$('[data-att-reason]',root).forEach(r=>r.value='');updateAttSummary(root)};root.__t83_att_base=base;updateAttSummary(root)}
function updateAttSummary(root){const base=root.__t83_att_base||[],rows=collectAttendance(root,base);const box=$('[data-att-summary]',root);if(box)box.innerHTML=attKpis(attendanceSummary(rows.map((x,i)=>Object.assign({},base[i],{_status:x.attendance_status}))))}

