function openClassAttendance(mount,ctx){const classId=$('[data-ca-class]',mount).value,date=$('[data-ca-date]',mount).value,btn=$('[data-ca-open]',mount);if(!classId)return flash(mount,'Select a class first.','warn');const done=busy(btn,'OPENING…');rpc('r174_teacher_class_attendance_entry',{p_class_id:classId,p_attendance_date:date}).then(d=>renderClassAttendanceEntry(mount,ctx,d)).catch(e=>flash(mount,errorText(e),'error')).finally(done)}
function renderClassAttendanceEntry(mount,ctx,d){const body=$('[data-ca-body]',mount),rows=d.rows||[],c=d.class||{};body.innerHTML=panel(c.class_code+' · '+val(d.attendance_date,''),val(c.class_teacher_names,'Class attendance'),'<div data-att-summary>'+attKpis(attendanceSummary(rows.map(r=>Object.assign({},r,{_status:r.attendance_status||'PRESENT'}))))+'</div><div class="t83-actions" style="justify-content:flex-start;margin-bottom:5px"><button class="t83-btn light small" data-mark-all-present>MARK ALL PRESENT</button><span class="t83-pill '+statusClass(d.workflow_status==='SUBMITTED'?'READY':'INCOMPLETE')+'">'+esc(d.workflow_status||'DRAFT')+'</span></div><div class="t83-table-wrap t83-desktop-only"><table class="t83-table t83-att-table"><colgroup><col style="width:48px"><col style="width:145px"><col><col style="width:74px"><col style="width:145px"><col style="width:260px"></colgroup><thead><tr><th>NO</th><th>SDMS</th><th>STUDENT</th><th>SEX</th><th>STATUS</th><th>REASON</th></tr></thead><tbody>'+attRowsHtml(rows)+'</tbody></table></div><div class="t83-mobile-list">'+attMobileHtml(rows)+'</div><div class="t83-savebar"><button class="t83-btn blue" data-ca-save>SAVE DRAFT</button><button class="t83-btn green" data-ca-submit>SUBMIT ATTENDANCE</button></div>');wireAttendanceRows(body,rows);$('[data-ca-save]',body).onclick=e=>saveClassAttendance(mount,d,e.currentTarget,false);$('[data-ca-submit]',body).onclick=e=>saveClassAttendance(mount,d,e.currentTarget,true)}
function saveClassAttendance(mount,d,btn,submit){const body=$('[data-ca-body]',mount),rows=collectAttendance(body,d.rows||[],true),err=validateAttendance(rows);if(err)return flash(mount,err,'warn');const c=ctxIds(),done=busy(btn,submit?'SUBMITTING…':'SAVING…');rpc('save_class_attendance',{p_academic_year_id:c.ayId,p_term_id:c.termId,p_class_id:d.class.id,p_attendance_date:d.attendance_date,p_rows:rows,p_submit:submit,p_notes:null}).then(x=>{flash(mount,submit?'Attendance submitted successfully.':'Attendance draft saved.','success');renderClassAttendanceEntry(mount,LAST_CTX,x)}).catch(e=>flash(mount,'Attendance save failed: '+errorText(e),'error')).finally(done)}

