function renderSubjectAttendanceEntry(mount,ctx,d){const body=$('[data-sa-body]',mount),rows=d.rows||[],c=d.context||{},l=d.__lesson||{};body.innerHTML=panel((c.class_code||l.class_code)+' · '+(c.subject_name||l.subject_name),fmtTime(l.start_time)+'–'+fmtTime(l.end_time)+' · '+val(c.lesson_date,''),'<div data-att-summary>'+attKpis(attendanceSummary(rows.map(r=>Object.assign({},r,{_status:r.attendance_status||'PRESENT'}))))+'</div><div class="t83-actions" style="justify-content:flex-start;margin-bottom:5px"><button class="t83-btn light small" data-mark-all-present>MARK ALL PRESENT</button><span class="t83-pill '+statusClass(d.workflow_status==='SUBMITTED'?'READY':'INCOMPLETE')+'">'+esc(d.workflow_status||'DRAFT')+'</span></div><div class="t83-table-wrap t83-desktop-only"><table class="t83-table t83-att-table"><colgroup><col style="width:48px"><col style="width:145px"><col><col style="width:74px"><col style="width:145px"><col style="width:260px"></colgroup><thead><tr><th>NO</th><th>SDMS</th><th>STUDENT</th><th>SEX</th><th>STATUS</th><th>REASON</th></tr></thead><tbody>'+attRowsHtml(rows)+'</tbody></table></div><div class="t83-mobile-list">'+attMobileHtml(rows)+'</div><div class="t83-savebar"><button class="t83-btn blue" data-sa-save>SAVE DRAFT</button><button class="t83-btn green" data-sa-submit>SUBMIT ATTENDANCE</button></div>');wireAttendanceRows(body,rows);$('[data-sa-save]',body).onclick=e=>saveSubjectAttendance(mount,d,e.currentTarget,false);$('[data-sa-submit]',body).onclick=e=>saveSubjectAttendance(mount,d,e.currentTarget,true)}
function saveSubjectAttendance(mount,d,btn,submit){const body=$('[data-sa-body]',mount),rows=collectAttendance(body,d.rows||[],false),err=validateAttendance(rows);if(err)return flash(mount,err,'warn');const c=ctxIds(),x=d.context||{},l=d.__lesson||{},done=busy(btn,submit?'SUBMITTING…':'SAVING…');rpc('save_subject_attendance',{p_academic_year_id:c.ayId,p_term_id:c.termId,p_class_id:x.class_id||l.class_id,p_subject_id:x.subject_id||l.subject_id,p_lesson_date:x.lesson_date,p_rows:rows,p_period_id:x.period_id||l.period_id,p_submit:submit,p_notes:null}).then(z=>{z.__lesson=l;flash(mount,submit?'Subject attendance submitted successfully.':'Subject attendance draft saved.','success');renderSubjectAttendanceEntry(mount,LAST_CTX,z)}).catch(e=>flash(mount,'Attendance save failed: '+errorText(e),'error')).finally(done)}

