 page(mount,ctx,true);mount.innerHTML=serviceHead('Lesson Plans','Create, save draft and submit plans for your assigned class / subject','<button class="t83-btn green small" data-t83-refresh>REFRESH</button>')+'<div data-lp-body><div class="t85-inline-state">Lesson-plan area is ready; confirming your current plans…</div></div>';wireBack(mount,ctx);
