/* R186.85 fail-visible guard: no unhandled teacher operation is allowed to fail silently. */
let T85_LAST_GLOBAL_ERROR=0;
function teacherErrorNotice(message){const now=Date.now();if(now-T85_LAST_GLOBAL_ERROR<1800)return;T85_LAST_GLOBAL_ERROR=now;notify(message,'error')}
window.addEventListener('unhandledrejection',event=>{if(!document.body.hasAttribute('data-t83-view'))return;const reason=event&&event.reason;teacherErrorNotice('Operation failed: '+errorText(reason))});
window.addEventListener('error',event=>{if(!document.body.hasAttribute('data-t83-view'))return;if(event&&event.target&&event.target!==window){teacherErrorNotice('A required page resource could not load. Refresh once and retry.');return}if(event&&event.error)teacherErrorNotice('Screen error: '+errorText(event.error))},true);

